#include <iostream>
using namespace std;

void printLine() {
    cout << "--------" << endl;
}

void showSquare(int n) {
    cout << n << " squared is " << n * n << endl;
}

int readMarks() {
    int m;
    cin >> m;
    return m;
}

double average(int a, int b, int c) {
    return (a + b + c) / 3.0;
}

int main() {
    printLine();
    showSquare(6);
    int marks = readMarks();
    cout << "Marks = " << marks << endl;
    cout << "Average = " << average(70, 85, 90) << endl;
    printLine();
    return 0;
}

#include <iostream>
using namespace std;

int test(int n) {
    if (n > 0) {
        return 1;
    }
    cout << "not positive" << endl;
    return 0;
}

int main() {
    cout << test(5) << endl;
    cout << test(-2) << endl;
    return 0;
}

